function make(key, name) {
  const C = forwardRef(function Icon({ size = 24, fill, strokeWidth, absoluteStrokeWidth, weight, className, style, ...rest }, ref) {
    void strokeWidth;
    void absoluteStrokeWidth;
    const d = D[key];
    const solid = (weight === 'fill' || (fill && fill !== 'none')) && d.f;
    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 256 256"
        fill="currentColor"
        className={className ? `icon ${className}` : 'icon'}
        style={style}
        aria-hidden={rest['aria-label'] ? undefined : true}
        {...rest}
        dangerouslySetInnerHTML={{ __html: solid ? d.f : d.r }}
      />
    );
  });
  C.displayName = name;
  return C;
}

